import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ClienteList = () => {
  const [clientes, setClientes] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Requisição para obter a lista de clientes
    axios.get('/clientes')
      .then(response => {
        setClientes(response.data); // Atualiza o estado com a lista de clientes
      })
      .catch(error => {
        setError('Erro ao carregar a lista de clientes');
        console.error(error);
      });
  }, []);

  // Função para excluir um cliente
  const handleDelete = (id) => {
    axios.delete(`/clientes/${id}`)
      .then(() => {
        setClientes(clientes.filter(cliente => cliente.id !== id)); // Remove o cliente da lista local
      })
      .catch((error) => {
        console.error("Erro ao excluir cliente", error);
      });
  };

  return (
    <div>
      <h1>Lista de Clientes</h1>
      {error && <p>{error}</p>}
      <ul>
        {clientes.map(cliente => (
          <li key={cliente.id}>
            <div>
              <strong>{cliente.nome}</strong> - {cliente.email} - {cliente.telefone}
              <button onClick={() => handleDelete(cliente.id)} style={{ marginLeft: "10px" }}>Excluir</button>
              {/* Adicione um botão para editar, que pode redirecionar para um formulário de edição */}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ClienteList;
